package com.vaijunto.controller;
import com.vaijunto.dto.*; import com.vaijunto.service.ConversationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/conversations") @RequiredArgsConstructor public class ConversationController {private final ConversationService service; @GetMapping public List<ConversationDto> list(Authentication a){return service.list(a.getName());} @GetMapping("/{id}/messages") public List<MessageDto> history(@PathVariable UUID id,Authentication a){return service.history(id,a.getName());} @PostMapping("/{id}/messages") public MessageDto send(@PathVariable UUID id,@Valid @RequestBody SendMessageRequest r,Authentication a){return service.send(id,r,a.getName());} @PatchMapping("/{conversationId}/messages/{messageId}") public MessageDto edit(@PathVariable UUID conversationId,@PathVariable UUID messageId,@RequestBody Map<String,String> body,Authentication a){return service.edit(conversationId,messageId,body.get("body"),a.getName());} @DeleteMapping("/{conversationId}/messages/{messageId}") public void delete(@PathVariable UUID conversationId,@PathVariable UUID messageId,Authentication a){service.delete(conversationId,messageId,a.getName());} @PostMapping("/{id}/reports") public Map<String,UUID> report(@PathVariable UUID id,@Valid @RequestBody ReportMessagesRequest r,Authentication a){return Map.of("id",service.report(id,r,a.getName()));} @PostMapping("/{id}/official-actions") public void officialAction(@PathVariable UUID id,@Valid @RequestBody OfficialActionRequest r,Authentication a){service.officialAction(id,r.action(),a.getName());}}
